#!/usr/bin/env python3
import os, base64

DIRS = ['prompts', 'prompts/coding', 'prompts/fedspeak', 'prompts/sales', 'src', 'src/prompty']

FILES = {
    'README.md': '',
    'app.py': '',
    'prompts/coding/bug_report_triage.md': '',
    'prompts/coding/code_review_assistant.md': '',
    'prompts/fedspeak/press_release_summarizer.md': '',
    'prompts/fedspeak/rate_decision_explainer.md': '',
    'prompts/sales/cold_email.md': '',
    'prompts/sales/follow_up.md': '',
    'src/prompty/__init__.py': 'IiIiUHJvbXB0eSBwYWNrYWdlIGluaXRpYWxpemF0aW9uLgoKVGhpcyBwYWNrYWdlIGNvbnRhaW5zIHNoYXJlZCB1dGlsaXRpZXMgZm9yIHRoZSBQcm9tcHR5IFN0cmVhbWxpdCBhcHBsaWNhdGlvbi4KIiIiCgpfX2FsbF9fID0gW10K',
    'src/prompty/utils.py': '',
}

def main():
    # Create directories
    for d in DIRS:
        os.makedirs(d, exist_ok=True)

    # Write files
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        full_path = os.path.abspath(path)
        dirpath = os.path.dirname(full_path)
        os.makedirs(dirpath, exist_ok=True)
        with open(full_path, "wb") as f:
            f.write(data)

if __name__ == "__main__":
    main()
